CREATE TABLE `halamanstatis` (
  `id_halaman` int(5) NOT NULL AUTO_INCREMENT,
  `judul` varchar(100) NOT NULL,
  `judul_seo` varchar(100) NOT NULL,
  `isi_halaman` text NOT NULL,
  `tgl_posting` date NOT NULL,
  `gambar` varchar(100) NOT NULL,
  `username` varchar(50) CHARACTER SET latin1 COLLATE latin1_general_ci NOT NULL,
  `dibaca` int(5) NOT NULL DEFAULT '1',
  `jam` time NOT NULL,
  `hari` varchar(20) CHARACTER SET latin1 COLLATE latin1_general_ci NOT NULL,
  PRIMARY KEY (`id_halaman`)
) ENGINE=MyISAM AUTO_INCREMENT=69 DEFAULT CHARSET=latin1;
INSERT INTO `halamanstatis` (`id_halaman`, `judul`, `judul_seo`, `isi_halaman`, `tgl_posting`, `gambar`, `username`, `dibaca`, `jam`, `hari`) VALUES (46,'Tentang HTC | Training and Consulting','tentang-htc--training-and-consulting','<h6 style=\"text-align: center; \" source=\"\" sans=\"\" pro\",=\"\" -apple-system,=\"\" blinkmacsystemfont,=\"\" \"segoe=\"\" ui\",=\"\" roboto,=\"\" \"helvetica=\"\" neue\",=\"\" arial,=\"\" sans-serif,=\"\" \"apple=\"\" color=\"\" emoji\",=\"\" ui=\"\" symbol\";=\"\" color:=\"\" rgb(0,=\"\" 0,=\"\" 0);=\"\" text-align:=\"\" center;\"=\"\"><img src=\"https://pusatpelatihanpajak.com/asset/images/logonew27.png\" style=\"width: 432px;\"></h6><h6 style=\"text-align: center; \"><p class=\"MsoNormal\" style=\"text-align: justify; line-height: 24px;\"><span style=\"color: rgb(75, 75, 75); font-size: 12pt;\">HTC Training &amp; Consulting (HTC) merupakan perusahaan yang bergerak dibidang Jasa Pendidikan, Pelatihan, dan Pengembangan Akuntansi, Manajemen, Hukum, Pajak, Perbankan, jasa pembukuan dan jasa konsultasi yang berpusat di Yogyakarta. HTC merupakan jawaban dari keinginan masyarakat yang membutuhkan pemahaman terutama dibidang Akuntansi dan Perpajakan.</span></p><p class=\"MsoNormal\" style=\"text-align: justify; line-height: 24px;\"><span style=\"color: rgb(75, 75, 75); font-size: 12pt;\">Dengan memberikan layanan berupa training dan konsultansi maka HTC mengharapkan Wajib Pajak dapat menjalankan hak dan kewajiban perpajakannya secara mandiri dengan menyiapkan karyawan yang professional dan mempunyai kemampuan teknikal dan analisis atas laporan laporan perpajakannya.</span></p><p class=\"MsoNormal\" style=\"text-align: justify; line-height: 24px;\"><span style=\"color: rgb(75, 75, 75); font-size: 12pt;\">Perkembangan dunia usaha dan banyaknya peraturan perpajakan menjadikan Wajib Pajak harus selalu mengupdate peraturan perpajakan yang ada agar tidak terjatuh pada kesalahan yang berakibat pada sanksi atau denda perpajakan mulai dari 2%, 50%, 100%, 150%, 200% bahkan 400%. </span></p><p class=\"MsoNormal\" style=\"text-align: justify; line-height: 24px;\"><span style=\"color: rgb(75, 75, 75); font-size: 12pt; font-family: inherit;\">Besarnya sanksi tersebut dapat mengakibatkan kesulitan likuiditas perusahaan baik dalam jangka pendek maupun jangka panjang. Untuk menghindari sanksi tersebut maka wajib pajak ditutuntut untuk dapat menjalankan hak dan kewajibannya sesuai dengan peraturan yang berlaku.</span><br></p><p class=\"MsoNormal\" style=\"text-align: justify; line-height: 24px;\"><span style=\"color: rgb(75, 75, 75); font-size: 12pt;\"><br></span></p><p class=\"MsoNormal\" style=\"text-align: justify; line-height: 24px;\"><span style=\"color: rgb(75, 75, 75); font-size: 12pt;\"><br></span></p></h6>','2014-04-07','','admin',551,'13:10:57','Senin'),(53,'Legalitas Izin Praktik','legalitas-izin-praktik','<p style=\"margin: 0in 0in 0.0001pt; text-align: center; line-height: 24px; background: rgb(252, 252, 252); vertical-align: top;\"><img src=\"https://pusatpelatihanpajak.com/asset/images/DSC_4636.jpg\" style=\"width: 1213.2px;\"><span style=\"font-weight: bolder;\"><span source=\"\" sans=\"\" pro\";\"=\"\" style=\"color: rgb(75, 75, 75); border: 1pt none windowtext; padding: 0in;\"><br></span></span></p><p style=\"margin: 0in 0in 0.0001pt; text-align: center; line-height: 24px; background: rgb(252, 252, 252); vertical-align: top;\"><span style=\"font-weight: bolder;\"><span source=\"\" sans=\"\" pro\";\"=\"\" style=\"color: rgb(75, 75, 75); border: 1pt none windowtext; padding: 0in;\"><br></span></span></p><p style=\"margin: 0in 0in 0.0001pt; text-align: center; line-height: 24px; background: rgb(252, 252, 252); vertical-align: top;\"><span style=\"font-weight: bolder;\"><span source=\"\" sans=\"\" pro\";\"=\"\" style=\"color: rgb(75, 75, 75); border: 1pt none windowtext; padding: 0in;\">Sambutan Direktur  HTC Training and Consulting</span></span><span style=\"color: rgb(54, 54, 53);\"><o:p></o:p></span></p><p style=\"margin: 0in 0in 0.0001pt; text-align: justify; line-height: 24px; background: rgb(252, 252, 252); vertical-align: top; outline: 0px;\"><span style=\"outline: 0px;\"><span source=\"\" sans=\"\" pro\";\"=\"\" style=\"color: rgb(54, 54, 53);\"> </span></span></p><p style=\"margin: 0in 0in 0.0001pt; text-align: justify; line-height: 24px; background: rgb(252, 252, 252); vertical-align: top; outline: 0px;\"><span source=\"\" sans=\"\" pro\";\"=\"\" style=\"color: rgb(75, 75, 75); border: 1pt none windowtext; padding: 0in;\">Perkembangan dunia usaha saat ini menuntut lulusan akuntansi memiliki pemahaman yang baik dan kompetensi yang CUKUP dibidang perpajakan. Perubahan peraturan perpajakan yang sangat cepat dan dinamis manjadikan Wajib Pajak harus selalu mengikuti perubahan tersebut secara tepat waktu agar terhindar dari berbagai kesalahan terkait dengan peraturan yang ada. Dengan semikian dibutuhkan SDM yang handal dan berkualitas untuk dapat menyajikan Laporan keuangan dan laporan perpajakan yang sesuai dengan peraturan perpajakan yang berlaku di Indonesia. Hal ini menjadi peluang bagi lulusan SMA/SMK dan perguruan tinggi bagi mereka yang memiliki soft skill dibidang perpajakan.</span><span style=\"color: rgb(54, 54, 53);\"><o:p></o:p></span></p><p style=\"margin: 0in 0in 0.0001pt; text-align: justify; line-height: 24px; background: rgb(252, 252, 252); vertical-align: top; outline: 0px;\"><span source=\"\" sans=\"\" pro\";\"=\"\" style=\"color: rgb(54, 54, 53);\"> </span></p><p style=\"margin: 0in 0in 0.0001pt; text-align: justify; line-height: 24px; background: rgb(252, 252, 252); vertical-align: top; outline: 0px;\"><span source=\"\" sans=\"\" pro\";\"=\"\" style=\"color: rgb(75, 75, 75); border: 1pt none windowtext; padding: 0in;\">Lulusan yang ingin memiliki kompetensi dan softskill perpajakan dapat mengikuti program yang diselenggarakan oleh HTC Training & Consulting. HTC telah menyiapkan program-program yang berkualitas sehingga dengan mengikuti program yang ada akan menciptakan keunggulan kompetitif bagi lulusannya untuk memasuki dunia kerja. Dengan keunggulan kompetitif tersebut akan membantu perusahaan dalam menjalankan pembukuan dan kewajiban perapajakannya</span><span style=\"color: rgb(54, 54, 53);\"><o:p></o:p></span></p><p style=\"margin: 0in 0in 0.0001pt; text-align: justify; line-height: 24px; background: rgb(252, 252, 252); vertical-align: top; outline: 0px;\"><span source=\"\" sans=\"\" pro\";\"=\"\" style=\"color: rgb(54, 54, 53);\"> </span></p><p><span style=\"outline: 0px;\"><u1:p></u1:p><span style=\"outline: 0px;\"></span></span></p><p style=\"margin: 0in 0in 0.0001pt; text-align: justify; line-height: 24px; background: rgb(252, 252, 252); vertical-align: top; outline: 0px;\"><span style=\"color: rgb(75, 75, 75); border: 1pt none windowtext; padding: 0in;\">HTC sebagai perusahaan yang bergerak di bidang jasa Jasa Pendidikan, Pelatihan, dan Pengembangan Akuntansi, Manajemen, Hukum, Pajak, Perbankan secara terus menerus mengupdate program yang ada sesuai dengan kebutuhan perusahaan. Dengan demikian, perusahaan akan dapat dengan mudah mengakses peraturan-peraturan yang ada dengan mengikuti program yang diselenggarakan oleh HTC Training & Consulting.</span></p><p style=\"margin: 0in 0in 0.0001pt; text-align: justify; line-height: 24px; background: rgb(252, 252, 252); vertical-align: top; outline: 0px;\"><span style=\"color: rgb(75, 75, 75); border: 1pt none windowtext; padding: 0in;\"><br></span></p><p style=\"margin: 0in 0in 0.0001pt; text-align: center; line-height: 24px; background: rgb(252, 252, 252); vertical-align: top;\"><span style=\"color: rgb(7, 55, 99); font-size: 30pt; background-color: transparent; font-family: Roboto; font-variant-ligatures: none; text-decoration-line: inherit; white-space: pre-wrap;\">Izin Praktik</span><br></p><div id=\"h.qk13c7syazvb\" class=\"CobnVe aP9Z7e\" style=\"margin-bottom: 0px; font-family: sans-serif; white-space: pre-wrap;\"></div><h2 id=\"h.qk13c7syaz